// Real .glb furniture/appliance meshes — the swap-in for buildFurnitureObject's
// hand-stacked box/cylinder primitives (see components/FloorPlan3D.tsx), from two
// sources. public/assets/furniture-cc0/ is vendored, unmodified geometry from
// Kenney's "Furniture Kit" (CC0 1.0 / public domain, see that directory's
// LICENSE.txt). public/assets/furniture-sand3d/ is originally generated by this
// project's own real part-based programs (scripts/sand3d/*.py, Apache-2.0 `sand3d`
// tool, https://github.com/Sandflow-ai/sand3d) at the exact same real-world
// dimensions the old parametric placeholders used (wardrobe 72in, dresser 32in,
// nightstand 24in, TV stand 20in, bookshelf 72in w/ 3 shelves, fridge 68in, stove
// 36in+cooktop, kitchen island 36in, armchair 3ft sq, coffee table 18in, office chair
// 18in seat/5-caster base, single bed 3.2ftx6.5ft, toilet 16in bowl/20in tank, bathtub
// 2.6ftx5ft/16in wall, bath vanity sink 32in counter, kitchen sink 36in counter) — see
// that directory's LICENSE.txt for provenance. This is additive: a furniture item
// whose type has no entry here keeps rendering the existing parametric geometry,
// exactly as before.
"use client";

import * as THREE from "three";
import { GLTFLoader } from "three/examples/jsm/loaders/GLTFLoader.js";
import type { FurnitureType } from "./layout/types";

/**
 * Every vendored CC0 mesh (sofa, bed, table, chair, desk — see
 * public/assets/furniture-cc0/LICENSE.txt) plus every originally-generated sand3d
 * mesh (wardrobe, dresser, nightstand, tv_stand, bookshelf, fridge, stove,
 * kitchen_island, armchair, coffee_table, office_chair, bed_single, toilet, bathtub,
 * sink_bath, sink_kitchen — see public/assets/furniture-sand3d/LICENSE.txt and
 * scripts/sand3d/*.py) is wired here, each via the exact same real-mesh swap-in
 * path in FloorPlan3D.tsx. Mapped to the catalog type each source model actually
 * depicts (bedDouble -> bed_queen, the plain table -> dining_table, the plain
 * chair -> dining_chair, desk -> desk, stove.glb -> stove) — any other
 * FurnitureType with no entry here keeps rendering the existing parametric
 * geometry, exactly as before.
 */
export const FURNITURE_GLB_ASSETS: Partial<Record<FurnitureType, string>> = {
  sofa: "/assets/furniture-cc0/sofa.glb",
  bed_queen: "/assets/furniture-cc0/bed.glb",
  dining_table: "/assets/furniture-cc0/table.glb",
  dining_chair: "/assets/furniture-cc0/chair.glb",
  desk: "/assets/furniture-cc0/desk.glb",
  wardrobe: "/assets/furniture-sand3d/wardrobe.glb",
  dresser: "/assets/furniture-sand3d/dresser.glb",
  nightstand: "/assets/furniture-sand3d/nightstand.glb",
  tv_stand: "/assets/furniture-sand3d/tv_stand.glb",
  bookshelf: "/assets/furniture-sand3d/bookshelf.glb",
  fridge: "/assets/furniture-sand3d/fridge.glb",
  stove: "/assets/furniture-sand3d/stove.glb",
  kitchen_island: "/assets/furniture-sand3d/kitchen_island.glb",
  // Third sand3d pass (2026-11-06, later still): the remaining FurnitureType values
  // that were still plain parametric primitives.
  armchair: "/assets/furniture-sand3d/armchair.glb",
  coffee_table: "/assets/furniture-sand3d/coffee_table.glb",
  office_chair: "/assets/furniture-sand3d/office_chair.glb",
  bed_single: "/assets/furniture-sand3d/bed_single.glb",
  toilet: "/assets/furniture-sand3d/toilet.glb",
  bathtub: "/assets/furniture-sand3d/bathtub.glb",
  sink_bath: "/assets/furniture-sand3d/sink_bath.glb",
  sink_kitchen: "/assets/furniture-sand3d/sink_kitchen.glb",
};

let cachedLoader: GLTFLoader | null = null;
function getLoader(): GLTFLoader {
  if (!cachedLoader) cachedLoader = new GLTFLoader();
  return cachedLoader;
}

const modelPromiseCache = new Map<string, Promise<THREE.Object3D>>();

/**
 * Loads (and caches) the real mesh at `url`, resolving to a fresh, independent
 * clone every call so multiple placed instances of the same piece (e.g. two
 * sofas in one plan) never share a single Object3D across the scene graph.
 * Never rejects the caller into an unhandled state the render loop has to
 * special-case: load failures reject the returned promise and the caller
 * (FloorPlan3D) is expected to keep its already-rendered parametric fallback.
 */
export function loadFurnitureModel(url: string): Promise<THREE.Object3D> {
  let cached = modelPromiseCache.get(url);
  if (!cached) {
    cached = new Promise<THREE.Object3D>((resolve, reject) => {
      getLoader().load(
        url,
        (gltf) => resolve(gltf.scene),
        undefined,
        (err) => reject(err instanceof Error ? err : new Error(String(err))),
      );
    });
    modelPromiseCache.set(url, cached);
  }
  return cached.then((scene) => scene.clone(true));
}

/**
 * Real-world footprint (feet) the vendored mesh was authored at, used to scale
 * the loaded model onto HomePlan's own furniture item dimensions instead of
 * stretching it to fit the floor plan's exact (often programmatically chosen)
 * rectangle — a uniform scale keeps the model's real proportions intact, the
 * same principle buildFurnitureObject already applies with its DIM constants.
 */
const GLB_NATIVE_FOOTPRINT_FT: Partial<Record<FurnitureType, { w: number; h: number }>> = {
  // Kenney's loungeSofa.glb measured bounding box: 0.98m x 0.41m footprint.
  sofa: { w: 0.98 / 0.3048, h: 0.41 / 0.3048 },
  // Kenney's bedDouble.glb measured bounding box: 0.956m x 1.125m footprint.
  bed_queen: { w: 0.956 / 0.3048, h: 1.125 / 0.3048 },
  // Kenney's table.glb measured bounding box: 0.841m x 0.447m footprint.
  dining_table: { w: 0.841 / 0.3048, h: 0.447 / 0.3048 },
  // Kenney's chair.glb measured bounding box: 0.2m x 0.2m footprint.
  dining_chair: { w: 0.2 / 0.3048, h: 0.2 / 0.3048 },
  // Kenney's desk.glb measured bounding box: 0.734m x 0.384m footprint.
  desk: { w: 0.734 / 0.3048, h: 0.384 / 0.3048 },
  // scripts/sand3d/wardrobe.py's exported mesh measured bounding box: 1.239m x 0.637m
  // (includes the cornice overhang and the door pulls protruding past the front face).
  wardrobe: { w: 1.239 / 0.3048, h: 0.637 / 0.3048 },
  // scripts/sand3d/dresser.py's exported mesh measured bounding box: 1.067m x 0.503m.
  dresser: { w: 1.067 / 0.3048, h: 0.503 / 0.3048 },
  // scripts/sand3d/nightstand.py's exported mesh measured bounding box: 0.488m x 0.498m.
  nightstand: { w: 0.488 / 0.3048, h: 0.498 / 0.3048 },
  // scripts/sand3d/tv_stand.py's exported mesh measured bounding box: 1.372m x 0.406m.
  tv_stand: { w: 1.372 / 0.3048, h: 0.406 / 0.3048 },
  // scripts/sand3d/bookshelf.py's exported mesh measured bounding box: 0.914m x 0.335m.
  bookshelf: { w: 0.914 / 0.3048, h: 0.335 / 0.3048 },
  // scripts/sand3d/fridge.py's exported mesh measured bounding box: 0.853m x 0.810m.
  fridge: { w: 0.853 / 0.3048, h: 0.81 / 0.3048 },
  // scripts/sand3d/stove.py's exported mesh measured bounding box: 0.762m x 0.690m.
  stove: { w: 0.762 / 0.3048, h: 0.69 / 0.3048 },
  // scripts/sand3d/kitchen_island.py's exported mesh measured bounding box: 1.676m x 0.914m.
  kitchen_island: { w: 1.676 / 0.3048, h: 0.914 / 0.3048 },
  // scripts/sand3d/armchair.py's exported mesh measured bounding box: 0.914m x 0.914m.
  armchair: { w: 0.914 / 0.3048, h: 0.914 / 0.3048 },
  // scripts/sand3d/coffee_table.py's exported mesh measured bounding box: 1.067m x 0.610m.
  coffee_table: { w: 1.067 / 0.3048, h: 0.61 / 0.3048 },
  // scripts/sand3d/office_chair.py's exported mesh measured bounding box: 0.549m x 0.531m.
  office_chair: { w: 0.549 / 0.3048, h: 0.531 / 0.3048 },
  // scripts/sand3d/bed_single.py's exported mesh measured bounding box: 0.975m x 1.981m.
  bed_single: { w: 0.975 / 0.3048, h: 1.981 / 0.3048 },
  // scripts/sand3d/toilet.py's exported mesh measured bounding box: 0.439m x 0.632m.
  toilet: { w: 0.439 / 0.3048, h: 0.632 / 0.3048 },
  // scripts/sand3d/bathtub.py's exported mesh measured bounding box: 0.792m x 1.524m.
  bathtub: { w: 0.792 / 0.3048, h: 1.524 / 0.3048 },
  // scripts/sand3d/sink_bath.py's exported mesh measured bounding box: 0.610m x 0.502m.
  sink_bath: { w: 0.61 / 0.3048, h: 0.502 / 0.3048 },
  // scripts/sand3d/sink_kitchen.py's exported mesh measured bounding box: 0.701m x 0.624m.
  sink_kitchen: { w: 0.701 / 0.3048, h: 0.624 / 0.3048 },
};

/** Uniform scale factor to best-fit `item`'s real footprint without distorting the mesh. */
export function furnitureModelFitScale(type: FurnitureType, item: { w: number; h: number }): number {
  const native = GLB_NATIVE_FOOTPRINT_FT[type];
  if (!native) return 1;
  const scaleX = item.w / native.w;
  const scaleZ = item.h / native.h;
  return (scaleX + scaleZ) / 2;
}
